INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('academie-de-l-arcane', 1, 'lore/academie-de-larcane', 'Informations officielles', '* **Date de création :** \-112', '\-112', 'chronologie', 'CODEX Maverick › Académie de l’arcane › Informations officielles');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('accord-du-sable', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact mineur :', '"Accord du Sable" (An 230\) (Désert Doré)', 'An 230', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact mineur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('age-de-fer', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact majeur :', 'Âge de fer (An 150\)', 'An 150', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact majeur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('age-de-fer', 2, 'lore/academie-de-larcane', 'Ambassadeur', 'Il s''agit à la base d''un système qui permettait de maintenir le taux de chakra à son plus haut, un groupe qui se sacrifie pour le bien de tous. Stopper cette chaîne pourrait avoir de graves conséquences. C''est ce qui va entraîner l''existence de l''Âge de Fer pour seulement 1 mois. En effet, il se trouve que la chaîne de la magie n’était plus utile car le chakra est tellement devenu stable dans le monde que faire ça revenait à pisser dans un violon.', 'pour seulement 1 mois', 'chronologie', 'CODEX Maverick › Académie de l’arcane › Ambassadeur');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('arme-liee-contre-armure-liee', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact mineur :', 'Arme lié VS Armure lié (An 1053\) (Erisia)', 'An 1053', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact mineur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('armee-des-non-morts', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact majeur :', 'L''armée des non-morts (An 320\)', 'An 320', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact majeur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('assassinat-d-un-empereur', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact mineur :', 'Assassinat d''un empereur humain et obstacle à l''apparition de l''Ottar Tour (An 499\) (Erisia)', 'An 499', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact mineur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('aujourd-hui', 1, 'lore/situation-actuelle', NULL, 'Aujourd’hui, il y a beaucoup de nations, les temples élémentaires fonctionnent comme des cités-états et les menaces dans le monde grossissent malgré tout le bon travail des nations ou des guildes. Dans l''ombre, des groupes cherchent à détruire des nations, détruire des temples, assassiner des gens, provoquer chaos et destruction voire faire réapparaître d''anciennes menaces chaotiques comme les élémentaires.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('bannissement-des-elfes-dores', 1, 'races/elfe-dore', 'Histoire', 'En l''An 50, un elfe argenté du nom de Notox Casus organisait une mutinerie, il a failli être tué, mais a pu continuer malgré tout son organisation et c''est en l''an 215 que les elfes dorés furent tous bannis par le Héros Argenté, ce même Notox Casus.', 'en l''an 215', 'chronologie', 'Les races › Elfe Doré › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('barrage-argente', 1, 'lore/barrage-argente', 'Histoire', 'En 680, l’Empire Argenté entama une politique de purification raciale et culturelle, jugeant certains clans « imparfaits ». Un groupe de dissidents refusa l’ordre d’extermination et s’enfuit vers le sud, poursuivi par une armée impériale.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('barrage-argente', 2, 'lore/empire-argente', 'Problèmes internes', 'tensions entre castes magiques et non-magiques, qui donnera plus tard une fuite d’une partie de la population en 680 et l’apparition du Barrage argenté.', 'en 680', 'chronologie', 'CODEX Maverick › Empire Argenté › Problèmes internes');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('baton-de-la-destruction', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact mineur :', 'Bâton de la Destruction (???) (Golopa)', '???', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact mineur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('baton-de-la-destruction', 2, 'lore/baton-de-la-destruction', 'Présentation', 'Le Bâton de la Destruction est une relique, forgée pendant l’ère “négative” où les cultes de la Création et de la Destruction s’affrontaient. Fait d’un bois encore inconnu, il est considéré comme l’un des artefacts magiques les plus dangereux jamais façonnés.', 'pendant l’ère “négative”', 'chronologie', 'CODEX Maverick › Bâton de la destruction › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('baton-de-la-destruction', 3, 'lore/baton-de-la-destruction', 'Rareté et Héritage', 'Il s’agit de l’un des artefacts les plus difficiles à réunir sous sa forme la plus pure : un objet unique, créé pendant une époque dont il ne reste presque aucun témoignage fiable, vu qu’il s’agit des époques “négatives”
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('belladones-fleurissantes', 1, 'lore/les-belladones-fleurissantes', 'Présentation', 'Fondées autour de l’an 115, les Belladones furent chargées d’une mission précise : façonner des armes humaines — des êtres capables de servir de catalyseurs magiques pour la branche principale. Leur création la plus tristement célèbre demeure les Pierres Empreintes de la Brume de Kcirevam, reliques imprégnées d’une essence, qui transforme celui ou celle qui la porte en sa version démoniaque.', 'autour de l’an 115', 'chronologie', 'CODEX Maverick › Les Belladones Fleurissantes › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('belladones-fleurissantes', 2, 'lore/les-belladones-fleurissantes', 'Présentation', '**Date de création :** 2 Umbro 115', '2 Umbro 115', 'chronologie', 'CODEX Maverick › Les Belladones Fleurissantes › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('blizzard-de-la-peine', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact mineur :', 'Le Blizzard de la Peine (An 200\) (Enohr)', 'An 200', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact mineur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('chaine-de-la-magie', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact mineur :', 'Fin de la chaîne de la magie (An 30\) (Erisia)', 'An 30', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact mineur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('chaine-de-la-magie', 2, 'lore/academie-de-larcane', 'Ambassadeur', 'Ce dragon argenté était le premier représentant de la déesse du chakra, mais l''entretien de la chaîne de la magie a commencé à lui peser fort dans son énergie divine, il n''est actuellement plus capable d''être parfaitement lucide malgré sa puissance. Il errait sans fin, accomplissant la chaîne sans voir les conséquences de son carnage. Et oui, en étant que peu lucide, il agissait comme une bête sauvage et tuait tous ceux qui n''étaient pas dignes de la chaîne.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('compagnie-du-fer-noir', 1, 'lore/compagnie-du-fer-noir', 'Présentation', 'Fondée en 114, la Compagnie du Fer Noir est une guilde elfique mêlant exploitation minière et mercenariat, spécialisée dans l’extraction et la protection du Fer Noir, un métal extrêmement rare et convoité. Installée au Fond de Rase, elle opère principalement dans la région de Rase, où elle contrôle le plus vaste gisement de Fer Noir connu à ce jour. Bien que relativement modeste par sa taille, la guilde s’est imposée comme un acteur incontournable grâce à sa discipline, sa loyauté stricte et son accès à un matériau stratégique d’une valeur inestimable.', 'Fondée en 114', 'chronologie', 'CODEX Maverick › Compagnie du Fer Noir › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('compagnie-du-fer-noir', 2, 'lore/compagnie-du-fer-noir', 'Présentation', 'L’exploitation attira rapidement les convoitises, et la guilde, dépourvue de force militaire, fit appel à Naral Belvani, chef d’une petite compagnie de mercenaires. Après deux années de conflit, un accord fut conclu : intégrer un pôle mercenaire permanent. Ainsi naquit la Compagnie du Fer Noir, spécialisée dans le minage et le mercenariat.', NULL, 'chronologie', 'CODEX Maverick › Compagnie du Fer Noir › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('conflit-de-ville-oeil', 1, 'lore/ville-oeil', 'Histoire', '(C-Courrier) En l’an 214, le conflit éclata pleinement.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('conflit-de-ville-oeil', 2, 'lore/ville-oeil', 'Éléments remarquables', 'L’histoire sanglante de l’an 214', 'l’an 214', 'chronologie', 'CODEX Maverick › Ville-Oeil › Éléments remarquables');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('confrerie-du-sang', 1, 'lore/confrerie-du-sang', 'Informations officielles', '* **Nom officiel :** Confrérie du Sang
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('confrerie-du-sang', 2, 'lore/confrerie-du-sang', 'Histoire', 'La Confrérie du Sang remonte à l’âge des premiers Orios, quand Arthurios Zoski, héros de la première vague, s’est révélé être l’élu de Brock lui même, décida d’ériger avec le temps un immense temple dans l’une des région les plus dangereuse de Maverick.', 'remonte à l’âge des premiers Orios', 'chronologie', 'CODEX Maverick › Confrérie du Sang › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('disparition-de-l-ordre-des-abeilles', 1, 'lore/ordre-des-abeilles', 'Organisation', 'Depuis leur disparition en 1160, on murmure que ces chevaliers sont devenus les gardiens de la ruche, des morts-vivants couverts de cire et de ruches animées, hantant les clairières arcanes où vivent encore les abeilles blanches.', 'en 1160', 'chronologie', 'CODEX Maverick › Ordre des Abeilles › Organisation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('dores-contre-argentes', 1, 'lore/temple-de-lespace-temps', 'Ambassadeur', '* *Notox*, Ambassadeur de l’Espace : un elfe argenté à la beauté irréelle. Autrefois noble et modeste, il s’éloigna de sa mission après le conflit “Dorés contre Argentés” (an 200-230), scellant les elfes dorés dans une dimension figée grâce à l’artefact divin le Pont Doré, une singularité semblable à un trou noir.', 'an 200-230', 'chronologie', 'CODEX Maverick › Temple de l’Espace/Temps › Ambassadeur');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('dores-contre-argentes', 2, 'lore/republique-forestier', 'Histoire', 'Éparpillés en de nombreuses poches à travers le monde, leurs communautés furent réduites en esclavage par les Elfes dorés pendant des siècles. Ce n’est qu’au cours de la grande guerre opposant Elfes dorés et Elfes argentés qu’ils purent profiter du chaos politique pour s’émanciper.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('drassahthac', 1, 'races/drassahthac', 'Présentation', 'Ce sont les premiers hybrides animaux à être apparus et ceux en l''an -450.', 'en l''an -450', 'chronologie', 'Les races › Drassah''thac › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('drassahthac', 2, 'races/drassahthac', 'Histoire', 'Ce sont les premiers hybrides animaux à avoir existé, ils sont arrivés peu après les humains, elfes et nains. Les Drassah''thac contrairement aux autres hybrides animaux qui vont suivre, ils ont accès à toutes les magies.', 'peu après les humains, elfes et nains', 'chronologie', 'Les races › Drassah''thac › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('eglise-du-sel', 1, 'lore/eglise-du-sel', 'Présentation', 'Installée dans la plus vaste mine de sel du monde sur la Plage Blanche à Engrevua, l’Église du Sel est devenue un pilier essentiel de l’approvisionnement mondial en sel, distribuant un sel pur et abondant à un prix symbolique afin que personne ne soit privé de ce bien vital. Générosité, accessibilité et solidarité constituent les fondements de leur foi, hérités de leur fondateur visionnaire, Victor de Saule.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('eglise-du-sel-aneantie', 1, 'lore/eglise-du-sel', 'Réputation', 'L’Église du Sel fut longtemps perçue comme une organisation humble, pacifique et admirable, dont la générosité touchait même les royaumes les plus éloignés. Leur sel bon marché ou offert sauva de nombreuses régions de la famine ou du déclin.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('elfes-argentes', 1, 'races/elfe-argente', 'Présentation', 'Cette race est apparue pour la première fois en l''an -100, après un "accident".', 'en l''an -100', 'chronologie', 'Les races › Elfe Argenté › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('elfes-argentes', 2, 'races/elfe-argente', 'Histoire', 'Tout comme les forestiers et les noirs, ils ont été des esclaves des dorés. Leur origine reste encore assez inconnue, mais on parle d''une expérience qui aura mal tourné qui a changé une partie des elfes dorés en elfe argenté.', NULL, 'chronologie', 'Les races › Elfe Argenté › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('elfes-forestiers', 1, 'races/elfe-forestier', 'Présentation', 'Cette race est apparue pour la première fois en l''an -50, c''est une lente évolution des elfes dorés dans le milieu forestier.', 'en l''an -50', 'chronologie', 'Les races › Elfe forestier › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('elfes-noirs', 1, 'races/elfe-noir', 'Présentation', 'Cette race est apparue pour la première fois en l''an 12, après une fuite possible grâce à Eaunoire.', 'en l''an 12', 'chronologie', 'Les races › Elfe Noir › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('elfes-noirs', 2, 'races/elfe-noir', 'Histoire', 'À l’origine, les Elfes Charbon étaient des elfes dorés condamnés à mort pour trahison, déshonneur ou crimes graves. Leur sentence consistait à être exposés à une corruption létale, jusqu’à ce que mort s’ensuive.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('elfes-noirs', 3, 'lore/eaunoire', 'Présentation', 'À une époque où seuls les Elfes Dorés peuplaient le monde, une méthode d’exécution était utilisée pour les crimes les plus graves : les condamnés étaient inondés de corruption jusqu’à en mourir.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('elfes-noirs', 4, 'lore/temple-noir', 'Histoire', 'L’origine du Temple noir est intimement liée au début de la déchéance des elfes dorés. Une époque où seul les Elfes Dorés existait, il existait une méthode d''exécution pour les crimes les plus graves, le principe était d''être bombardé de corruption jusqu''à la mort. Cette méthode fonctionnait sans souci jusqu’au jour où Eaunoire apparut. Il refusa catégoriquement que tout cela continue, sauvant ceux qui pouvaient encore l’être. C’est ainsi que naquirent les Elfes Dorés à la peau entièrement noire, malgré l’absence de toute corruption dans leur corps. Les générations suivantes conservèrent cette particularité. Ainsi sont nés les elfes noirs.', 'Une époque où seul les Elfes Dorés existait', 'chronologie', 'CODEX Maverick › Temple noir › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('empire-humain-et-calendrier', 1, 'lore/empire-humain', 'Présentation générale', 'Née en l’an 0 en même temps que le calendrier, l’Empire Humain est la plus vaste et la plus puissante entité politique du monde connu.', 'en l’an 0', 'chronologie', 'CODEX Maverick › Empire Humain › Présentation générale');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('empire-humain-et-calendrier', 2, 'lore/temple-de-lespace-temps', 'Organisation interne', '* **Les Chronarques :** Sages du temps, ce sont eux qui ont mis au point le Calendrier à l’an 0\. Une légende dit que les premières horloges ont été fabriquées là haut, l’horloge qu’on nomme aujourd’hui”l’horloge universelle” proviendrait d’un sablier du temple, c’est ce sablier qui a permis l’existence de l’horlogerie.', 'à l’an 0', 'chronologie', 'CODEX Maverick › Temple de l’Espace/Temps › Organisation interne');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('epee-400', 1, 'lore/400', 'Histoire et création', 'L’arme fut créée en 320 par Joseph Wiczkoblaz, un Martiale humain, forgeron passionné et adepte de la magie du sang. Sa vie bascula lorsqu’un raid des Crânes Rouges, une tribu de bandits redoutée à l’est de Golopa, ravagea son village natal, Uacourg, tuant notamment son meilleur ami.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('excalibur', 1, 'lore/excalibur', 'Période / Origine', 'An 21 \- Construction de l’arme\
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('excalibur', 2, 'lore/excalibur', 'Histoire et création', 'L’histoire d’Excalibur débute avec Charles Carsote, Templier du Temple de la Terre, héros reconnu pour sa loyauté et ses exploits au côté de l’Ambassadeur de la Terre.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('excalibur-deuxieme-porteur', 1, 'lore/excalibur', 'Période / Origine', 'An 43 \- Deuxième porteur : Shigun Dobarto', 'An 43', 'chronologie', 'CODEX Maverick › Excalibur › Période / Origine');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('excalibur-quatrieme-porteur', 1, 'lore/excalibur', 'Période / Origine', 'An 500 \- Quatrième porteur : Dreya (Joueur)', 'An 500', 'chronologie', 'CODEX Maverick › Excalibur › Période / Origine');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('excalibur-troisieme-porteur', 1, 'lore/excalibur', 'Période / Origine', 'An 253 \- Troisième porteur : Gaël l’argenté', 'An 253', 'chronologie', 'CODEX Maverick › Excalibur › Période / Origine');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('famine-a-mrode', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact mineur :', 'Famine a Mrode/Vent d''Or (An 808\) (Mrode)', 'An 808', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact mineur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('felfes', 1, 'races/felfe', 'Présentation', 'Ils sont apparus en l''an 80, une belle union taboue entre une grande fée et un elfe argenté.', 'en l''an 80', 'chronologie', 'Les races › Felfe › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('felfes', 2, 'races/felfe', 'Histoire', 'L’origine des felfes demeure incertaine, et nul ne sait avec certitude qui fut le premier de leur espèce. Selon une légende ancienne, leur naissance remonterait à l’union secrète entre le dirigeant des Elfes Argentés de l’époque et la grande reine des Farfadets. De cette relation serait née la première felfe : une femelle à la peau argentée.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('fin-de-l-empire-dore', 1, 'lore/empire-argente', 'Histoire', 'Des siècles d’oppression menèrent en 205 à une révolte violente. Les Elfes argentés massacrèrent leurs maîtres, détruisirent l’Empire Doré et exilèrent les survivants restants.', 'en 205', 'chronologie', 'CODEX Maverick › Empire Argenté › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('fin-de-l-empire-humain', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact majeur :', 'Fin de l''empire humain (An 1138\)', 'An 1138', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact majeur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('fin-des-ruines-rouges', 1, 'lore/ruines-rouges', 'La Fin des Ruines Rouge', 'En l''an 1151, Xavier Théris, l''héritier légitime de Joyeuse est venu en ces ruines avec son équipe de mercenaire pour mettre la main sur la bannière de l''absolu pour être légitime aux yeux du peuple sans nom d''être dirigé par celui qui remettra la Religion de l''Absolu en marche. Les Ruines Rouge n''existe plus et ont été remplacées par Vièrebourg, le Royaume des Héritiers des Dieux.', 'En l''an 1151', 'chronologie', 'CODEX Maverick › Ruines Rouges › La Fin des Ruines Rouge');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('flammes-bleues', 1, 'lore/les-flammes-bleues', 'Présentation', '* **Date de création :** 10 Celsius 342', '10 Celsius 342', 'chronologie', 'CODEX Maverick › Les Flammes Bleues › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('foudre-etincelante', 1, 'lore/foudre-etincelante', 'Histoire et création', 'L’origine de Foudre étincelante remonte à l’an 243, au cœur des cités naines. Franz Ammermann, un forgeron de génie, fervent adorateur de Volt et d’Aurora, rêvait de créer un dispositif capable d’éclairer et d’alimenter sa ville natale. Après des années d’essais infructueux avec des pièces élémentaires, il créa finalement une petite boîte géométrique d’une perfection telle qu’elle attira l’attention divine.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('grande-croisade', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact majeur :', 'La Grande Croisade (An 505\)', 'An 505', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact majeur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('guerisseurs-silencieux', 1, 'lore/guerisseurs-silencieux', 'Présentation', 'Les Guérisseurs Silencieux sont une branche dissidente du Temple Noir, formée par des prêtres et mages de la Corruption qui ont refusé de suivre la voie de la destruction. Rejetés et pourchassés par les éléments les plus extrêmes, ils ont choisi de retourner à ce qu’ils considèrent comme l’essence originelle de leur dieu : la guérison. et l’aide à autrui.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('guerre-interne-des-gardiens', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact mineur :', 'Guerre interne des Gardiens (An 945\) (Ici et là)', 'An 945', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact mineur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('guilde-mere-des-belladones', 1, 'lore/les-belladones-fleurissantes', 'Présentation', 'Les Belladones Fleurissantes forment une branche semi-autonome d’une guilde plus vaste et énigmatique, dont les racines remontent à l’an 38\. Cette guilde-mère, rarement mentionnée publiquement, serait intimement liée au concept de Destruction — dans son sens le plus métaphysique : celui de la fin nécessaire à toute création.', 'l’an 38', 'chronologie', 'CODEX Maverick › Les Belladones Fleurissantes › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 1, 'races/fenrir', 'Présentation', 'Apparu avec tous les autres hybrides animaux dans les ans -400 à -350.', 'dans les ans -400 à -350', 'chronologie', 'Les races › Fenrir › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 2, 'races/fenrir', 'Histoire', 'Ce sont les troisièmes hybrides animaux à être apparus sur Maverick. Selon la légende, les Fenrirs sont une création du Dieu de la Foudre, Volt. Dans des temps immémoriaux, les humains vivaient eux aussi en tribus et les braves loups cherchaient refuge lors des plus terribles hivers. Au départ méfiants, les humains ont accueilli les canidés dans leurs villages. Au fil des siècles, ils sont devenus dociles et devinrent ce que l''on appelle aujourd''hui des chiens. Mais pas tous les loups ne s''étaient soumis aux humains, certains ont choisi de rester en meutes, de rester sauvages, d''autres étaient envieux mais hésitants. Ils souhaitaient vivre la vie des paisibles chiens, sans renoncer à leur vie sauvage, et c''est là que le dieu de la Foudre tenta l''expérience : il métamorphosa plusieurs couples de ces loups admiratifs en ce que l''on appelle aujourd''hui des Fenrirs. On ignore bien évidemment quelles furent les intentions de Volt, mais ainsi soit-il. Les Fenrirs sont nés en -400 et sont maintenant ceux qui vivent en tribus.', 'en -400', 'chronologie', 'Les races › Fenrir › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 3, 'races/satyre', 'Présentation', 'Apparu avec tous les autres hybrides animaux dans les ans -400 à -350.', 'dans les ans -400 à -350', 'chronologie', 'Les races › Satyre › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 4, 'races/satyre', 'Histoire', 'La cinquième race hybride animale est née d’une manière particulièrement atypique. À l’origine, le premier satyre ne fut nul autre que Bauc, dieu de la débauche et des arts.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 5, 'races/jackalope', 'Présentation', 'Apparu avec tous les autres hybrides animaux dans les ans -400 à -350.', 'dans les ans -400 à -350', 'chronologie', 'Les races › Jackalope › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 6, 'races/jackalope', 'Histoire', 'Race humain lapin à l''origine du Dieu de la débauche, Bauc. Après l''arrivée des Satyres, Bauc voulait un peuple qui représente bien mieux sa passion pour l''art, les Jackalopes sont nés avec un talent naturel pour l''art.', 'Après l''arrivée des Satyres', 'chronologie', 'Les races › Jackalope › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 7, 'races/anansi', 'Présentation', 'Apparu avec tous les autres hybrides animaux dans les ans -400 à -350.', 'dans les ans -400 à -350', 'chronologie', 'Les races › Anansi › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 8, 'races/goleois', 'Présentation', 'Apparu avec tous les autres hybrides animaux dans les ans -400 à -350.', 'dans les ans -400 à -350', 'chronologie', 'Les races › Goleois › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 9, 'races/goleois', 'Histoire', 'Leur origine est assez inconnue mais on parlerait d''une secte d''humains qui aura subi une terrible malédiction mais dans leur malheur, ils ont réussi à transformer cette dernière en force et se sont transformés en les êtres que nous connaissons aujourd''hui.', NULL, 'chronologie', 'Les races › Goleois › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 10, 'races/kitsune', 'Présentation', 'Apparu avec tous les autres animaux hybrides dans les ans -400 à -350.', 'dans les ans -400 à -350', 'chronologie', 'Les races › Kitsune › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 11, 'races/kitsune', 'Histoire', 'Nous parlons d''une époque où les kitsunes un culte d''humains ayant subi une malédiction d''origine encore inconnue, les transformant en une abomination d''humain/renard. Mais un jour, les dieux ont eu pitié des kitsunes et les ont permis de s''adapter et de récupérer leur apparence humaine. Le premier d''entre eux nommé "le Grand Druide" aurait vu 3 dieux dans une vision, Séraphin, Aurora et Eoline. Persuadés, que c''est un signe divin, les kitsunes vouent un culte envers ces 3 dieux qui sont considérés comme les créateurs des kitsunes tels qu''on les connaît aujourd''hui.', NULL, 'chronologie', 'Les races › Kitsune › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 12, 'races/marcass', 'Présentation', 'Apparu avec tous les autres hybrides animaux dans les ans -400 à -350.', 'dans les ans -400 à -350', 'chronologie', 'Les races › Marcass › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 13, 'races/medusain', 'Présentation', 'Apparu avec tous les autres hybrides animaux dans les ans -400 à -350.', 'dans les ans -400 à -350', 'chronologie', 'Les races › Médusain › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 14, 'races/medusain', 'Histoire', 'Au tout début, les Médusains n’étaient autres que des humains nomades voyageant dans tout Maverick pour parler de leurs histoires et partager avec d’autres peuples leur foi envers leurs trois divinités : Océane la déesse de l’eau, Volt le dieu de la foudre et Aurora la déesse de la lumière. Hélas lors de l’un de leurs voyages, ils se mirent à dos Séraphe dieu de la guerre ; la raison de cette colère est aujourd’hui encore totalement inconnue de tous, sauf des chefs spirituels de chacune des quatre sociétés médusaines : Les urbains, les Médusains de la foudre, les Médusains de la lumière et les Médusains de l’eau.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 15, 'races/namazu', 'Présentation', 'Apparu avec tous les autres hybrides animaux dans les ans -400 à -350.', 'dans les ans -400 à -350', 'chronologie', 'Les races › Namazus › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 16, 'races/namazu', 'Histoire', 'C''est une race qui existe suite à une malédiction comme la plupart des hybrides animales, les membres d''une secte d''adorateurs d''Océane se sont fait maudire par Anna la Déesse de la Fortune pour des raisons encore obscures, ces derniers sont devenus des monstres mi-humains mi-requins, assoiffés de sang et totalement aveugles. Océane leur a permis de conserver une formes humaines hybrides requins, ce qui leur permet d''être les plus à l''aise dans l''eau, Brock a calmé leur soif de sang et Umbro leur a redonné la vue qu''ils avaient perdue.', NULL, 'chronologie', 'Les races › Namazus › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 17, 'races/olwman', 'Présentation', 'Apparu avec tous les autres hybrides animaux dans les ans -400 à -350.', 'dans les ans -400 à -350', 'chronologie', 'Les races › Olwman › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 18, 'races/olwman', 'Histoire', 'Les Origines de cette race sont très mystérieuses, on parle d''Umbro mais aussi de Notix dans leurs origines étant donné qu''ils peuvent posséder cette magie de manière innée, mais aussi pour leur côté très raffiné et aussi leur soif de savoir.', NULL, 'chronologie', 'Les races › Olwman › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('hybrides-animaux', 19, 'races/rokh', 'Présentation', 'Apparu avec tous les autres animaux hybrides autres dans les ans -400 à -350..', 'dans les ans -400 à -350', 'chronologie', 'Les races › Rokh › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('lamias', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact mineur :', 'Arrivés des Lamias (An 51\) (Erisia)', 'An 51', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact mineur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('lamias', 2, 'races/lamia', 'Présentation', 'Cette race extraplanaire est apparue la première fois en l''an 51.', 'en l''an 51', 'chronologie', 'Les races › Lamia › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('lamias', 3, 'races/lamia', 'Histoire', 'Elles sont arrivées grâce à une faille temporelle, depuis elles ont su se trouver un territoire et s''adapter à leur nouvel environnement. Elles sont divisées en 8 clans dénommés "Maison" avec chacune leur particularité, leur spécialité et leur dirigeante.', NULL, 'chronologie', 'Les races › Lamia › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('les-exaltes', 1, 'lore/les-exaltes', 'Présentation', 'Les Exaltés sont un petit ordre marginal, composé d’à peine une dizaine de fidèles, voués à Falathar, l’Ambassadeur du Feu. Contrairement aux prêtres traditionnels du Feu, le feu des Exaltés est celui de la purification, pas de la destruction.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('liberation-des-minotaures', 1, 'lore/londolor', 'Histoire', 'En l’an 200, lors d’une guerre contre les elfes noirs, les nains libèrent entièrement le peuple minotaure. Ce geste fondateur entraîne une alliance durable : les minotaures promettent leur force de travail et leur loyauté en échange de conditions de vie dignes et, surtout, d’une solution à leur stérilité.', 'En l’an 200', 'chronologie', 'CODEX Maverick › Londolor › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('liberation-des-minotaures', 2, 'races/minotaure', 'Histoire', 'Ce n’est qu’à la suite d’une guerre de territoire entre les Nains et les Elfes Charbon que leur destin changea. Les Nains libérèrent les Minotaures de leurs chaînes et leur offrirent refuge.', NULL, 'chronologie', 'Les races › Minotaure › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('liberation-des-minotaures', 3, 'races/nain', 'Histoire', 'Ce sont également les Nains qui, en l’an 280, libérèrent les Minotaures de la tyrannie des Elfes Charbon. Malgré cet acte, les relations entre les deux peuples ne se sont jamais véritablement apaisées.', 'en l’an 280', 'chronologie', 'Les races › Nain › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('majins', 1, 'races/majin', 'Présentation', 'Cette race est arrivée dans leur monde d''origine en -39.', 'en -39', 'chronologie', 'Les races › Majin › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('majins-en-masse', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact mineur :', 'Arrivés en masse des Majins (An 450\) (Erisia)', 'An 450', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact mineur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('majins-en-masse', 2, 'races/majin', 'Histoire', 'Les Majins ont réussi à créer un premier grand portail en l''an 450 en direction de Maverick et ainsi fut connue la première grande immigration des Majins vers les contrées humaines.', 'en l''an 450', 'chronologie', 'Les races › Majin › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('medecin-sans-frontiere', 1, 'lore/medecin-sans-frontiere', 'Présentation', 'Ce culte a été fondé par deux personnes en l’an 202 avec l’aide de l’ambassadeur de la lumière de l’époque :
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('medecin-sans-frontiere', 2, 'lore/medecin-sans-frontiere', 'Présentation', '**Date de création :** 202', '202', 'chronologie', 'CODEX Maverick › Médecin sans frontière › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('minotaures', 1, 'races/minotaure', 'Présentation', 'Apparu en l''an -50, contrairement aux autres hybrides animales, c''est une création alchimique.', 'en l''an -50', 'chronologie', 'Les races › Minotaure › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('minotaures-fertiles', 1, 'lore/londolor', 'Histoire', 'Après 160 années de recherches et d’efforts titanesques, les nains parviennent en l’an 360 à rendre les minotaures fertiles. Ce succès marque leur intégration totale dans la société naine.', 'en l’an 360', 'chronologie', 'CODEX Maverick › Londolor › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('minotaures-fertiles', 2, 'races/minotaure', 'Histoire', 'L’un des plus grands accomplissements de cette alliance fut atteint en l’an 360, lorsque les Nains parvinrent à résoudre un problème majeur : l’absence de reproduction naturelle chez les Minotaures. Jusqu’alors dépendants de procédés alchimiques, ils purent enfin voir apparaître les premières femelles de leur espèce. Dès lors, la race minotaure devint autonome et capable de se reproduire naturellement.', 'en l’an 360', 'chronologie', 'Les races › Minotaure › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('mutinerie-de-notox-casus', 1, 'races/elfe-dore', 'Histoire', 'En l''An 50, un elfe argenté du nom de Notox Casus organisait une mutinerie, il a failli être tué, mais a pu continuer malgré tout son organisation et c''est en l''an 215 que les elfes dorés furent tous bannis par le Héros Argenté, ce même Notox Casus.', 'En l''An 50', 'chronologie', 'Les races › Elfe Doré › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('or-de-londolor', 1, 'lore/londolor', 'Londolor Est', 'C’est en l’an 14 qu’ils découvrent un grand gisement d’or qui va leur permettre d’augmenter encore plus leur richesse, le jour de la découverte de ce gisement, la royauté avait associé les nains de l’est et de l’ouest pour y creuser le plus efficacement possible.', 'en l’an 14', 'chronologie', 'CODEX Maverick › Londolor › Londolor Est');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('or-de-londolor', 2, 'lore/londolor', 'Éléments remarquables', 'La découverte de l’or en l’an 14, tournant économique majeur.', 'en l’an 14', 'chronologie', 'CODEX Maverick › Londolor › Éléments remarquables');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('ordre-de-gardecroc', 1, 'lore/ordre-de-gardecroc', 'Présentations', 'Fondée en l’an 197, elle a vu le jour grâce à un Elfe forestier de la Terre nommé Marcus, un Orios de l’eau nommé Boris, ainsi qu’une Kitsune du vent nommée Yuna. L’ordre de Gardecroc est principalement relié au Temple de la Terre, même si des rumeurs disent que ceux du vent et de l’eau sont aussi dans sa confrérie, en réalité n’importe quelle magie peut rejoindre l’ordre, car n’importe qui peuvent aider.', 'en l’an 197', 'chronologie', 'CODEX Maverick › Ordre de Gardecroc › Présentations');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('ordre-de-gardecroc', 2, 'lore/ordre-de-gardecroc', 'Présentations', '* **Date de création :** 10 Drassah 197', '10 Drassah 197', 'chronologie', 'CODEX Maverick › Ordre de Gardecroc › Présentations');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('ordre-de-la-glace-rouge', 1, 'lore/ordre-de-la-glace-rouge', 'Présentation', '* **Date de création :** 20 Celsius 310', '20 Celsius 310', 'chronologie', 'CODEX Maverick › Ordre de la Glace Rouge › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('ordre-de-la-mort', 1, 'lore/ordre-de-la-mort', 'Présentation', 'Fondé en l’an 0 par un ancien moine renégat de la Chapelle des Os, l’Ordre de Chevalerie de la Mort est un culte militant voué à Evravonie, la déesse de la Vie et de la Mort.', 'en l’an 0', 'chronologie', 'CODEX Maverick › Ordre de la mort › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('ordre-de-la-mort', 2, 'lore/ordre-de-la-mort', 'Présentation', '* **Date de création :** 28 Evravonie 0', '28 Evravonie 0', 'chronologie', 'CODEX Maverick › Ordre de la mort › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('ordre-des-abeilles', 1, 'lore/ordre-des-abeilles', 'Présentation', 'Fondé en l’an 1140, l’Ordre des Abeilles est un petit groupe de dix chevaliers liés à la magie de l’Arcane. Leur mission sacrée est la protection des abeilles blanches, des créatures rares capables de produire un miel imprégné de chakra pur.', 'en l’an 1140', 'chronologie', 'CODEX Maverick › Ordre des Abeilles › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('ordre-des-abeilles', 2, 'lore/ordre-des-abeilles', 'Présentation', '**Date de création :** 1140', '1140', 'chronologie', 'CODEX Maverick › Ordre des Abeilles › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('ordre-du-brai', 1, 'lore/ordre-du-brai', 'Présentation', 'L’Ordre du Brai est une secte issue d’une scission du Temple Noir, née du fanatisme de certains adeptes jugeant leur temple d’origine trop modéré dans la propagation de la Corruption. Ces dissidents ont juré fidélité à Eaunoire sous sa forme la plus destructrice, celle du Dévoreur, et se sont enfoncés dans les marécages les plus denses du monde pour y bâtir leurs bastions.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('ordre-du-soleil', 1, 'lore/ordre-solaire', 'Présentation', 'L’Ordre du Soleil, également appelé Chevaliers Solaires, est une organisation militaire dévouée à l’éradication du vampirisme et de toute forme de non-mort pervertissant les terres. Né après l’apparition des premiers vampires, l’ordre s’est rapidement imposé comme le principal rempart contre ces créatures impies du sang.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('origine-du-monde', 1, 'lore/origine-du-monde', NULL, 'Tout commença avec deux forces : la Création et la Destruction.\
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('orios', 1, 'races/orios', 'Présentation', 'Cette race est arrivée en -430, peu de temps après les premiers humains.', 'en -430', 'chronologie', 'Les races › Orios › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('orios', 2, 'races/orios', 'Histoire', 'Ce sont les deuxièmes hybrides animaux à être apparus sur Maverick. Des rumeurs disent que les Orios sont une création du Dieu de la Force, Brock. D''autres parlent d''une secte vénérant ce même dieu, le dieu aurait accordé sa bénédiction sur la secte entière et les aurait changés en Orios.', 'les deuxièmes hybrides animaux à être apparus', 'chronologie', 'Les races › Orios › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('premier-drakos', 1, 'races/drakos', 'Présentation', 'Le premier drakos est apparu en l''an 100, c''était un Drakos de la terre issu d''une relation entre un Dragon de la terre et une humaine.', 'en l''an 100', 'chronologie', 'Les races › Drakos › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('premier-drakos', 2, 'lore/dragon', 'La naissance des Drakos', 'Lors de l''an 100, par un aveuglement de l’amour, une dragonne de la Terre et un prêtre humain de la Terre s’unirent. Leur union, déjà considérée comme impossible, donna naissance à un événement encore plus inconcevable : la dragonne tomba enceinte.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('premier-hujin', 1, 'races/hujin', 'Présentation', 'Le premier Hujin est arrivé en l''an 40, une belle histoire d''amour entre une majin et un humain qui a fini dans le sang.', 'en l''an 40', 'chronologie', 'Les races › Hujin › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('premier-hujin', 2, 'races/hujin', 'Histoire', 'Le premier Hujin est né sur le sol de Maverick d''un père Humain et d''une mère Majin, il s''est vite remarqué par les scientifiques de Maverick qui ne savaient pas ce qu''il était. Il s''est fait d''abord maltraiter par les Elfes Argentés et Noirs, jusqu''à se faire récupérer par les Humains, et là tout se déroulait bien mieux.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('premier-impact', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact majeur :', 'Guerre des Temples/Apparition de l''Ottar Monde (An 20\)', 'An 20', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact majeur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('premier-impact', 2, 'lore/temple-de-lespace-temps', 'Histoire', 'Lorsque le Premier Impact survint en l’an 20, une série d’anomalies magiques ravagea le ciel et les fondations dimensionnelles. Les tensions latentes entre Notix et Capse explosèrent : leurs disciples se divisèrent, chaque tour se retranchant dans sa vision du monde.', 'en l’an 20', 'chronologie', 'CODEX Maverick › Temple de l’Espace/Temps › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('premier-impact', 3, 'lore/temple-de-lespace-temps', 'Présentation générale', 'Mais lors du Premier Impact, en l’an \-30, le temple entra dans une guerre interne d’une ampleur dévastatrice. Les deux divinités, autrefois liées, se déchirèrent — provoquant l’effondrement de leur propre sanctuaire.', 'en l’an \-30', 'chronologie', 'CODEX Maverick › Temple de l’Espace/Temps › Présentation générale');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('premier-impact', 4, 'lore/temple-de-lespace-temps', 'Ambassadeur', 'Mais la guerre éclata avant son éveil. Le processus fut interrompu… et le résultat imparfait donna naissance à un être instable, aujourd’hui connu sous le nom de Mora, Dieu du Vide. Ainsi, la création de l’ambassadeur du Temple de l’Espace/Temps fut l’origine directe du Vide.', NULL, 'chronologie', 'CODEX Maverick › Temple de l’Espace/Temps › Ambassadeur');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('premier-impact', 5, 'lore/mora', 'Présentation', 'À une époque où existait encore le Temple de l’Espace/Temps, il était destiné à devenir l’Ambassadeur de cette magie. Rien de moins. Mais tout a dérapé lorsque les deux divinités ont commencé à se quereller pour des raisons encore inconnues. Leur conflit a déclenché une guerre intestine au sein même du Temple, lors de ce que l’on nomme aujourd’hui le Premier Impact. Cela avait scindé la religion en deux.', 'lors de ce que l’on nomme aujourd’hui le Premier Impact', 'chronologie', 'CODEX Maverick › Mora › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('premier-impact', 6, 'lore/seraphe', 'Histoire', 'Bien qu’il ne soit pas l’unique cause du Premier Impact, il en fut l’un des catalyseurs, poussant les dieux et les mortels à s’affronter dans une série de conflits dévastateurs.', 'du Premier Impact', 'chronologie', 'CODEX Maverick › Séraphe › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('premier-impact', 7, 'lore/seraphe', 'Outils divins', '**Amulette de Puissance :** Amulette unique forgée dans les flammes du Premier Impact. Elle accorde à son porteur une force surhumaine et une endurance sans égale tant que dure la bataille.', 'dans les flammes du Premier Impact', 'chronologie', 'CODEX Maverick › Séraphe › Outils divins');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('premier-impact', 8, 'lore/ordre-de-la-glace-rouge', 'Présentation', 'Cet ordre existe depuis la fin du Premier impact, quand la paix entre feu et glace a été déclarée.', 'depuis la fin du Premier impact', 'chronologie', 'CODEX Maverick › Ordre de la Glace Rouge › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('proliferation-des-vampires', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact majeur :', 'Prolifération des vampires/Remède contre le vampirisme (An 625\)', 'An 625', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact majeur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('redecouverte-de-ville-oeil', 1, 'lore/ville-oeil', 'Histoire', 'Les recherches indiquent que l’édifice était autrefois dédié à un culte de la personnalité centré sur une dirigeante nommée Mata, décrite comme porteuse d’un potentiel illimité. Mais un événement tragique fit basculer son règne : elle sombra dans une démence profonde.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('ruines-de-noname-scellees', 1, 'lore/ruines-rouges', 'Ruines de Noname', 'Selon la légende, ces ruines renfermeraient le lieu où se réunissent l''Ordre des Ambassadeurs pour discuter des affaires internes, des châtiments ou bien des problèmes plus généraux.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('temple-noir', 1, 'lore/temple-noir', 'Informations officielles', '**Date de création :** 52', '52', 'chronologie', 'CODEX Maverick › Temple noir › Informations officielles');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('temple-noir', 2, 'lore/temple-noir', 'Histoire', 'En remerciement, les survivants fondèrent le Temple noir à Rase, érigeant ses colonnes dans un style inspiré des anciens sanctuaires elfiques, mais noircies par le marbre. Ce temple ne fut pas bâti dans la conquête ou la gloire, mais dans la culpabilité, la reconnaissance et la recherche d’un sens à cette transformation forcée.', NULL, 'chronologie', 'CODEX Maverick › Temple noir › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('temples-elementaires', 1, 'lore/temple-du-feu', 'Présentation générale', '**Date de création :** 1 Séraphin, an \-30', '1 Séraphin, an \-30', 'chronologie', 'CODEX Maverick › Temple du Feu › Présentation générale');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('temples-elementaires', 2, 'lore/temple-de-la-foudre', 'Informations officielles', 'Date de création : 1 Volt \-30', '1 Volt \-30', 'chronologie', 'CODEX Maverick › Temple de la Foudre › Informations officielles');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('temples-elementaires', 3, 'lore/temple-de-la-foudre', 'Histoire', 'Fondé peu avant la Grande Union des Temples, le Temple de la Foudre fut établi pour canaliser les puissantes tempêtes qui ravageait autrefois la mer orientale.', 'peu avant la Grande Union des Temples', 'chronologie', 'CODEX Maverick › Temple de la Foudre › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('temples-elementaires', 4, 'lore/temple-de-la-lumiere', 'Informations officielles', '* Date de création : 1 Aurora, an \-30', '1 Aurora, an \-30', 'chronologie', 'CODEX Maverick › Temple de la Lumière › Informations officielles');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('temples-elementaires', 5, 'lore/temple-de-la-lumiere', 'Histoire', 'Fondé avant même l’aube des grandes civilisations, le Temple de la Lumière fut la première institution à unifier sous un même symbole les forces du Bien. Sa création remonte à la première apparition d’Aurora sur le monde, lorsqu’un éclat céleste serait tombé du firmament, donnant naissance à cette Tour Cristalline.', 'avant même l’aube des grandes civilisations', 'chronologie', 'CODEX Maverick › Temple de la Lumière › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('temples-elementaires', 6, 'lore/temple-de-la-terre', 'Informations officielles', 'Date de création : 1 Dimitri \-30', '1 Dimitri \-30', 'chronologie', 'CODEX Maverick › Temple de la Terre › Informations officielles');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('temples-elementaires', 7, 'lore/temple-de-la-terre', 'Histoire', 'Le Temple de la Terre fut fondé durant la même ère que les autres grands temples élémentaires, lorsque les divinités décidèrent de manifester leur présence à travers des bastions physiques.', 'durant la même ère que les autres grands temples élémentaires', 'chronologie', 'CODEX Maverick › Temple de la Terre › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('temples-elementaires', 8, 'lore/temple-de-leau', 'Informations officielles', 'Date de création : 1 Océane \-30', '1 Océane \-30', 'chronologie', 'CODEX Maverick › Temple de l’Eau › Informations officielles');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('temples-elementaires', 9, 'lore/temple-de-leau', 'Histoire', 'La fondation du Temple de l’Eau remonte à l’ère pré-Impériale, lors des premiers développements autour du lac sacré d’Erisia. À cette époque, la Déesse Océane aurait offert à ses fidèles une partie de ses eaux pour y ériger un sanctuaire. Le Temple connut très tôt une expansion rapide grâce à son rôle pacificateur dans les conflits régionaux.', 'l’ère pré-Impériale', 'chronologie', 'CODEX Maverick › Temple de l’Eau › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('temples-elementaires', 10, 'lore/temple-de-lombre', 'Informations officielles', '**Date de création :** 1 Umbro \-30', '1 Umbro \-30', 'chronologie', 'CODEX Maverick › Temple de l’Ombre › Informations officielles');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('temples-elementaires', 11, 'lore/temple-de-vent', 'Informations officielles', '* **Date de création :** 1 Éoline, an \-30', '1 Éoline, an \-30', 'chronologie', 'CODEX Maverick › Temple de Vent › Informations officielles');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('temples-elementaires', 12, 'lore/temple-de-vent', 'Histoire', 'Érigé à la demande directe d’Éoline, le Temple du Vent fut construit sur une île céleste proche des monts verts qui était bloqué dans un énorme nuage noir. La réussite du peuple du vent fait qu’Éoline dissipa le nuage par son souffle divin.', NULL, 'chronologie', 'CODEX Maverick › Temple de Vent › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('terres-grises', 1, 'lore/les-impacts-mineur-et-majeur', 'Impact mineur :', 'Apparition des Terres Grises (???) (Mrode)', '???', 'chronologie', 'CODEX Maverick › Les Impacts mineur et majeur › Impact mineur :');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('terres-grises', 2, 'lore/terre-grise', 'Origine et mystère', 'Les origines exactes de la Terre Grise restent inconnues. Les récits parlent d’une tragédie ancienne, d’un événement où la magie de la Terre et celle du Vide se seraient entremêlées de manière catastrophique. Le résultat aurait été une réaction incontrôlable, une fusion contre-nature transformant le sol en une matière hybride, ni totalement minérale, ni totalement organique.', 'restent inconnues', 'chronologie', 'CODEX Maverick › Terre grise › Origine et mystère');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('trois-premieres-races', 1, 'races/humain', 'Présentation', 'Cette race fait partie des 3 premières à être arrivées dans le monde avec les Nains et les Elfes Dorés.', 'des 3 premières à être arrivées dans le monde', 'chronologie', 'Les races › Humain › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('trois-premieres-races', 2, 'races/nain', 'Présentation', 'Cette race fait partie des 3 premières à être arrivées dans le monde avec les Humains et les Elfes Dorés.', 'des 3 premières à être arrivées dans le monde', 'chronologie', 'Les races › Nain › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('trois-premieres-races', 3, 'races/nain', 'Histoire', 'Arrivés peu après les Humains et les Elfes Dorés, les Nains ont rapidement trouvé leur place au sein des montagnes et des cavernes. Leur petite taille, particulièrement adaptée à l’exploration d’espaces étroits, leur a permis de s’y installer efficacement. Cela ne les a toutefois jamais empêchés de voir les choses en grand, fondant d’immenses cités creusées à même la roche.', 'Arrivés peu après les Humains et les Elfes Dorés', 'chronologie', 'Les races › Nain › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('trois-premieres-races', 4, 'races/elfe-dore', 'Présentation', 'Les elfes dorés comptent parmi les premières races à avoir foulé les terres de Maverick, aux côtés des Humains et des Nains. Leur arrivée ne s’est toutefois pas faite sans violence, marquant les débuts d’une cohabitation difficile entre les peuples.', 'parmi les premières races à avoir foulé les terres de Maverick', 'chronologie', 'Les races › Elfe Doré › Présentation');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('trois-premieres-races', 5, 'races/elfe-dore', 'Histoire', 'Cette race est apparue en même temps que les Humains et les Nains, chacun avait leur portion de territoire et personne ne venait empiéter sur l''autre.', 'en même temps que les Humains et les Nains', 'chronologie', 'Les races › Elfe Doré › Histoire');
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('vampirisme', 1, 'lore/vampires-primordiaux', 'Origine et malédiction', 'Les Vampires Primordiaux sont les tout premiers êtres à avoir porté le vampirisme. À l’origine, ils étaient des mortels ayant tenté de créer un nouveau pouvoir en manipulant la magie du Sang, sans l’autorisation divine.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('vampirisme', 2, 'lore/vampires-primordiaux', 'Le pacte divin et la naissance du vampirisme', 'Mais les neuf Vampires Primordiaux proposèrent un accord : ils diffuseraient le vampirisme à travers le monde, offrant ainsi à d’autres mortels une forme de puissance issue indirectement du Dieu de la Force.
INSERT INTO evenement_extrait (evenement_id, rang, page_id, section, texte, date_brut, origine, source_ref) VALUES ('voeu-de-naito', 1, 'lore/eglise-du-sel', 'Réputation', 'Aujourd’hui, grâce au retour de Selcalibur et au vœu accompli par Naïto et ses compagnons en 701, l’Église renaît lentement, entourée d’un mélange de respect sacré et de nostalgie.', 'en 701', 'chronologie', 'CODEX Maverick › Église du Sel › Réputation');
